same-origin'); // ── the rules catch real breakages ── ok(hasProblem(edit('panel.html', s => s.replace('</body>', '<script>alert(1)</script></body>')), /inline script/), 'an inline script is caught'); ok(hasProblem(edit('panel.html', s => s.replace('</body>', '<script src="https://cdn.example.com/x.js"></script></body>')), /external script/), 'an external script is caught'); ok(hasProblem(edit('panel.html', s => s.replace('</head>', '<script defer src="/_vercel/insights/script.js"></script></head>')), /analytics|not a relative file/), 'the site analytics script is caught'); ok(hasProblem(edit('panel.html', s => s.replace('<body', '<body onload="init()"')), /inline event handler/), 'an inline event handler is caught'); ok(hasProblem(edit('panel.html', s => s.replace('href="panel.css"', 'href="/twitch-panel/panel.css"')), /stylesheet/), 'a site-relative stylesheet is caught'); ok(hasProblem(edit('mobile.html', s => s.replace(`href="${SITE}/terms"`, 'href="/terms"')), /site-relative path|not absolute/), 'a site-relative link is caught'); ok(hasProblem(edit('panel.js', s => s + "
