(pre.headers.get('access-control-allow-methods') ?? ''), 'a preflight from the extension's domain is allowed (Authorization header, POST)'); const get = await call('GET', '/api/twitch/season', EXT); ok(get.headers.get('access-control-allow-origin') === EXT && get.headers.get('vary')?.includes('Origin'), 'a normal call from the extension's domain gets the headers'); ok((await call('GET', '/api/version', EXT)).headers.get('access-control-allow-origin') === EXT, '/api/version is covered too'); for (const bad of ['https://evil.example.com', 'https://abc.ext-twitch.tv.evil.com', 'http://abc.ext-twitch.tv', 'https://ext-twitch.tv', 'https://a.b.ext-twitch.tv', 'null']) { const r = await call('GET', '/api/twitch/season', bad); ok(!r.headers.get('access-control-allow-origin'), `${bad} is not allowed`); const p = await call('OPTIONS', '/api/twitch/login', bad); ok(p.status === 204 && !p.headers.get('access-control-allow-origin'), `a preflight from ${bad} is answered without permission`); } ok(!(await call('GET', '/api/twitch/season')).headers.get('access-control-allow-origin'), 'a call with no Origin gets no CORS headers'); ok((await call('OPTIONS', '/api/twitch/login', 'http://localhost:4400')).headers.get('access-control-allow-origin') === 'http://localhost:4400', 'in development another local port may call the API'); } console.log('twitch package checks passed');

